fn describe_def_site(site: DefSite) -> Dict {
    let path = RootedPath::new(
        VirtualRoot::Package(REPO_ROOT),
        VirtualPath::virtualize(Path::new(""), Path::new(site.path)).unwrap(),
    );
    dict! {
        "path" => path,
        "key" => site.key,
    }
}

/// Provides details about acceptable values for a parameter or return value.
fn describe_cast_info(info: &CastInfo) -> Dict {
    match info {
        CastInfo::Any => dict! {
            "kind" => "any"
        },
        CastInfo::Value(value, details) => dict! {
            "kind" => "value",
            "value" => value.clone(),
            "details" => *details,
        },

